-- SnapInbox catalog space: bilingual product, FAQ, subscription terms, and public legal pages.
-- The TypeScript fallback remains the reproducible source for builds without Supabase.
do $migration$
declare
  product_id uuid;
begin
  insert into public.apps (
    slug, name, tagline, tagline_en, short_description, short_description_en,
    long_description, long_description_en, problem, problem_en, benefits,
    benefits_en, features, features_en, audience, audience_en, status, featured,
    category, platform, website_url, support_email, icon_url, cover_image_url,
    screenshots, primary_cta_label, primary_cta_label_en, primary_cta_url,
    secondary_cta_label, secondary_cta_label_en, secondary_cta_url,
    color_primary, color_secondary, seo_title, seo_description, pricing,
    free_features, free_features_en, pro_features, pro_features_en, updated_at
  ) values (
    'snapinbox', 'SnapInbox: Action Inbox', 'Convierte capturas en acciones verificadas.', 'Turn screenshots into verified next steps.',
    'Importa una captura o PDF, revisa lo que encuentra SnapInbox y conviértelo en una acción útil sin enviar tu contenido a la nube.', 'Import a screenshot or PDF, review what SnapInbox finds, and turn it into a useful next step without sending your content to the cloud.',
    'SnapInbox da un lugar a las capturas que guardaste para después. Extrae fechas, horas, lugares, enlaces, precios y referencias en el dispositivo, conserva la evidencia y te deja confirmar cada acción antes de enviarla a Calendario o Recordatorios.', 'SnapInbox gives the screenshots you saved for later a place to go. It extracts dates, times, places, links, prices, and references on the device, keeps the evidence, and lets you confirm each action before sending it to Calendar or Reminders.',
    'Las capturas importantes se pierden entre fotos, PDF, mensajes y recordatorios mentales. Cuando vuelves a ellas, ya no recuerdas qué querías hacer.', 'Important screenshots get lost among photos, PDFs, messages, and mental reminders. When you return to them, you no longer remember what you meant to do.',
    ARRAY['Inbox de acción: Reúne lo que guardaste para después y separa lo pendiente de lo archivado.', 'Procesamiento local: Reconoce texto y datos útiles sin enviar tus capturas o PDF a un servidor.', 'Evidencia y confianza: Revisa el origen de cada campo y corrige antes de guardar.', 'Acciones bajo control: Confirma cada evento, recordatorio, enlace o exportación antes de ejecutarlo.'],
    ARRAY['Action inbox: Bring together what you saved for later and separate pending items from archived work.', 'On-device processing: Recognize text and useful details without sending screenshots or PDFs to a server.', 'Evidence and confidence: Review each field''s source and correct it before saving.', 'Actions under your control: Confirm every event, reminder, link, or export before it runs.'],
    ARRAY['Captura desde Fotos, Archivos, Share y Atajos: Importa el material desde la superficie que ya estás usando.', 'OCR y extracción local: Detecta fechas, horas, lugares, enlaces, precios y referencias con confianza y evidencia.', 'Revisión guiada: Corrige campos ambiguos y conserva el contenido original junto con tus decisiones.', 'Inbox y Archivo: Busca elementos revisados, marca lo resuelto y conserva lo que todavía necesita atención.', 'Calendario y Recordatorios: Crea acciones únicamente después de tu confirmación explícita.', 'Widget y App Shortcuts: Consulta y captura sin romper el flujo de trabajo.', 'SnapInbox Pro: Suscripciones mensual y anual opcionales gestionadas por Apple y RevenueCat.'],
    ARRAY['Import from Photos, Files, Share, and Shortcuts: Bring in material from the surface you already use.', 'On-device OCR and extraction: Detect dates, times, places, links, prices, and references with confidence and evidence.', 'Guided review: Correct ambiguous fields and keep the original content alongside your decisions.', 'Inbox and Archive: Search reviewed items, mark work complete, and keep what still needs attention.', 'Calendar and Reminders: Create actions only after your explicit confirmation.', 'Widget and App Shortcuts: Check and capture without breaking your workflow.', 'SnapInbox Pro: Optional monthly and annual subscriptions managed by Apple and RevenueCat.'],
    'Personas que guardan capturas, documentos, reservas, recibos, enlaces y tareas para actuar sobre ellos más tarde.', 'People who save screenshots, documents, bookings, receipts, links, and tasks to act on later.',
    'coming_soon', true, 'Productividad', ARRAY['iOS', 'iPadOS'], 'https://lbernardo-dev.github.io/apps/es/casos/snapinbox/', 'romerodev.app@gmail.com', 'assets/images/snapinbox/AppIcon-1024.png', 'assets/images/snapinbox/AppIcon-1024.png', ARRAY[]::text[],
    'Ver soporte y lanzamiento', 'View support and launch', '/es/casos/snapinbox/soporte/', 'Privacidad', 'Privacy', '/es/casos/snapinbox/privacidad/', '#5b5ce2', '#24c8a5',
    'SnapInbox: convierte capturas en acciones | RomeroDev', 'Importa capturas y PDF, extrae información en el dispositivo y confirma cada acción con SnapInbox para iPhone y iPad.',
    '[{"name":"Mensual","name_en":"Monthly","price":"Precio en App Store","cadence":"/mes","cadence_en":"/month","description":"Apple mostrará el precio, impuestos y condiciones finales antes de confirmar.","description_en":"Apple shows the final price, taxes, and terms before confirmation.","isIndicative":true},{"name":"Anual","name_en":"Annual","price":"Precio en App Store","cadence":"/año","cadence_en":"/year","description":"La disponibilidad y elegibilidad dependen del territorio y de Apple.","description_en":"Availability and eligibility depend on territory and Apple.","featured":true,"badge":"Mejor valor","badge_en":"Best value","isIndicative":true}]'::jsonb,
    ARRAY['Inbox y Archivo local', 'OCR y extracción en el dispositivo', 'Revisión y confirmación de acciones', 'Widget, Share y Atajos'], ARRAY['Local Inbox and Archive', 'On-device OCR and extraction', 'Action review and confirmation', 'Widget, Share, and Shortcuts'], ARRAY['Más espacio para capturas', 'Funciones Premium de flujo de trabajo', 'Suscripción restaurable entre dispositivos con el mismo Apple Account'], ARRAY['More room for captures', 'Premium workflow features', 'Restorable subscription across devices with the same Apple Account'], now()
  ) on conflict (slug) do update set
    name = excluded.name, tagline = excluded.tagline, tagline_en = excluded.tagline_en, short_description = excluded.short_description, short_description_en = excluded.short_description_en,
    long_description = excluded.long_description, long_description_en = excluded.long_description_en, problem = excluded.problem, problem_en = excluded.problem_en,
    benefits = excluded.benefits, benefits_en = excluded.benefits_en, features = excluded.features, features_en = excluded.features_en, audience = excluded.audience, audience_en = excluded.audience_en,
    status = excluded.status, featured = excluded.featured, category = excluded.category, platform = excluded.platform, website_url = excluded.website_url, support_email = excluded.support_email,
    icon_url = excluded.icon_url, cover_image_url = excluded.cover_image_url, screenshots = excluded.screenshots, primary_cta_label = excluded.primary_cta_label, primary_cta_label_en = excluded.primary_cta_label_en,
    primary_cta_url = excluded.primary_cta_url, secondary_cta_label = excluded.secondary_cta_label, secondary_cta_label_en = excluded.secondary_cta_label_en, secondary_cta_url = excluded.secondary_cta_url,
    color_primary = excluded.color_primary, color_secondary = excluded.color_secondary, seo_title = excluded.seo_title, seo_description = excluded.seo_description, pricing = excluded.pricing,
    free_features = excluded.free_features, free_features_en = excluded.free_features_en, pro_features = excluded.pro_features, pro_features_en = excluded.pro_features_en, updated_at = now()
  returning id into product_id;

  delete from public.app_faqs where app_id = product_id;
  insert into public.app_faqs (app_id, question, question_en, answer, answer_en, sort_order) values
    (product_id, '¿Se envían mis capturas a la nube?', 'Are my screenshots sent to the cloud?', 'No. La versión actual procesa y guarda el contenido de SnapInbox localmente. RevenueCat solo recibe la información técnica necesaria para gestionar la suscripción Pro; no recibe tus capturas ni resultados OCR.', 'No. The current version processes and stores SnapInbox content locally. RevenueCat receives only the technical information needed to manage the Pro subscription; it does not receive your screenshots or OCR results.', 0),
    (product_id, '¿Necesito una cuenta?', 'Do I need an account?', 'No. El flujo principal funciona sin cuenta y sin conexión. Las compras se asocian al Apple Account que usa el App Store.', 'No. The main flow works without an account or connection. Purchases are associated with the Apple Account used by the App Store.', 1),
    (product_id, '¿Puedo confiar en las fechas detectadas?', 'Can I trust detected dates?', 'SnapInbox muestra confianza y evidencia, pero una extracción puede equivocarse. Revisa el contenido original y corrige los campos antes de guardar o crear una acción.', 'SnapInbox shows confidence and evidence, but extraction can be wrong. Review the original content and correct fields before saving or creating an action.', 2),
    (product_id, '¿Crea eventos o recordatorios automáticamente?', 'Does it create events or reminders automatically?', 'No. Las acciones de Calendario y Recordatorios requieren tu confirmación explícita después de revisar los datos.', 'No. Calendar and Reminders actions require your explicit confirmation after you review the data.', 3),
    (product_id, '¿Cómo elimino un elemento?', 'How do I delete an item?', 'Puedes eliminarlo desde la app y ajustar la retención de la captura original. Al desinstalar SnapInbox se eliminan sus copias locales controladas por la app.', 'You can delete it in the app and adjust source-capture retention. Uninstalling SnapInbox removes its app-controlled local copies.', 4),
    (product_id, '¿Cómo restauro SnapInbox Pro?', 'How do I restore SnapInbox Pro?', 'Usa Restaurar compras dentro de SnapInbox con el mismo Apple Account. Apple y RevenueCat comprobarán el estado de la suscripción; las suscripciones se gestionan desde Ajustes > tu nombre > Suscripciones.', 'Use Restore Purchases in SnapInbox with the same Apple Account. Apple and RevenueCat will check the subscription status; subscriptions are managed in Settings > your name > Subscriptions.', 5);

  delete from public.app_legal_pages where app_id = product_id;
  insert into public.app_legal_pages (app_id, kind, title, title_en, body, body_en, updated_at) values
    (product_id, 'privacy', 'Política de privacidad de SnapInbox', 'SnapInbox Privacy Policy', E'Esta política explica qué información trata SnapInbox y qué permanece en tus dispositivos. Los derechos imperativos de tu país prevalecen.\n## 1. Responsable y contacto\nResponsable: Lester Romero Bernardo (RomeroDev), Valencia, España. Contacto: romerodev.app@gmail.com.\n## 2. Procesamiento local\nLas capturas, imágenes, PDF, texto OCR, campos detectados, correcciones, etiquetas y elementos guardados se procesan y conservan localmente. Las fechas y acciones son propuestas y requieren tu revisión.\n## 3. Contenido que no enviamos\nNo enviamos capturas, fotografías, PDF, texto OCR, nombres, direcciones, códigos, precios, enlaces, eventos, recordatorios ni contenido guardado a nuestros servidores. No se necesita una cuenta.\n## 4. Apple y RevenueCat\nApple procesa pagos mediante StoreKit. RevenueCat puede recibir un identificador anónimo de usuario, productos, estado de compra o entitlement, información de transacción y datos técnicos necesarios para mantener Pro y restaurar compras. No recibe capturas ni resultados OCR. Consulta su política: https://www.revenuecat.com/privacy-policy.\n## 5. Analítica y seguimiento\nLa configuración actual no tiene Firebase activo ni analítica o Crashlytics habilitados por defecto. No usamos seguimiento entre apps o sitios web ni publicidad personalizada.\n## 6. Conservación y derechos\nPuedes revisar, exportar y eliminar tus elementos desde la app; al desinstalarla se eliminan sus copias locales. Puedes contactar con romerodev.app@gmail.com para ejercer derechos aplicables o informar de una incidencia.', E'This policy explains what SnapInbox processes and what stays on your devices. Mandatory rights in your country of residence prevail.\n## 1. Controller and contact\nController: Lester Romero Bernardo (RomeroDev), Valencia, Spain. Contact: romerodev.app@gmail.com.\n## 2. On-device processing\nScreenshots, images, PDFs, OCR text, detected fields, corrections, labels, and saved items are processed and stored locally. Dates and actions are proposals and require your review.\n## 3. Content we do not send\nWe do not send screenshots, photos, PDFs, OCR text, names, addresses, codes, prices, links, events, reminders, or saved content to our servers. No account is required.\n## 4. Apple and RevenueCat\nApple processes payments through StoreKit. RevenueCat may receive an anonymous app user ID, products, purchase or entitlement status, transaction information, and technical data needed to maintain Pro and restore purchases. It does not receive screenshots or OCR results. See its policy: https://www.revenuecat.com/privacy-policy.\n## 5. Analytics and tracking\nThe current configuration has no active Firebase project and does not enable analytics or Crashlytics by default. We do not use cross-app or cross-site tracking or personalized advertising.\n## 6. Retention and rights\nYou can review, export, and delete items in the app; uninstalling removes its local copies. Contact romerodev.app@gmail.com to exercise applicable rights or report a privacy concern.', now()),
    (product_id, 'terms', 'Términos de uso de SnapInbox', 'SnapInbox Terms of Use', E'Estos términos regulan SnapInbox junto con la Política de privacidad y las reglas del App Store. Los derechos irrenunciables no quedan limitados.\n## 1. Servicio\nSnapInbox importa imágenes y PDF, reconoce información, conserva capturas revisadas y propone Calendario, Recordatorios, enlaces, exportaciones, widgets, Share y Atajos. No garantiza que una extracción sea correcta.\n## 2. Revisión\nDebes revisar el contenido original y confirmar cada acción. SnapInbox no sustituye tu criterio ni debe ser la única fuente para decisiones médicas, financieras, legales, de viaje o seguridad.\n## 3. Uso autorizado\nImporta solo material que tengas derecho a usar. No vulneres la privacidad de terceros, infrinjas la ley ni interfieras con la seguridad de Apple o la app.\n## 4. Licencia\nSnapInbox y sus materiales pertenecen a Lester Romero Bernardo (RomeroDev) o sus licenciantes. Se concede una licencia personal, limitada y no transferible conforme al Standard EULA de Apple: https://www.apple.com/legal/internet-services/itunes/dev/stdeula/.\n## 5. Compras y contacto\nLas funciones Pro se ofrecen mediante Apple In-App Purchase. Apple gestiona pagos, renovaciones y reembolsos. Soporte: romerodev.app@gmail.com.\n## 6. Disponibilidad\nLa app se proporciona tal como está en la medida permitida por la ley. Apple es tercero beneficiario de estos términos. Se aplica la legislación de España sin perjuicio de derechos imperativos.', E'These terms govern SnapInbox together with the Privacy Policy and App Store rules. Non-waivable rights are not limited.\n## 1. Service\nSnapInbox imports images and PDFs, recognizes information, keeps reviewed captures, and suggests Calendar, Reminders, links, exports, widgets, Share, and Shortcuts. It does not guarantee extraction accuracy.\n## 2. Review\nYou must review original content and confirm each action. SnapInbox does not replace your judgment or serve as the sole source for medical, financial, legal, travel, or safety decisions.\n## 3. Authorized use\nImport only material you may use. Do not invade another person privacy, break the law, or interfere with Apple or app security.\n## 4. License\nSnapInbox and its materials belong to Lester Romero Bernardo (RomeroDev) or licensors. You receive a personal, limited, non-transferable license under Apple Standard EULA: https://www.apple.com/legal/internet-services/itunes/dev/stdeula/.\n## 5. Purchases and contact\nPro features use Apple In-App Purchase. Apple handles payments, renewals, and refunds. Support: romerodev.app@gmail.com.\n## 6. Availability\nThe app is provided as is to the extent permitted by law. Apple is a third-party beneficiary. Spanish law applies without prejudice to mandatory rights.', now()),
    (product_id, 'subscriptions', 'Condiciones de suscripción de SnapInbox Pro', 'SnapInbox Pro Subscription Terms', E'Estas condiciones complementan los Términos de uso y la Política de privacidad. Apple muestra el precio, impuestos, moneda, duración y elegibilidad antes de confirmar.\n## 1. Planes\nSnapInbox Pro puede ofrecer planes mensual y anual auto-renovables para funciones Premium.\n## 2. Renovación\nLa suscripción se renueva automáticamente salvo cancelación al menos 24 horas antes del final del periodo. Apple puede cobrar dentro de las 24 horas anteriores.\n## 3. Gestionar y restaurar\nGestiona o cancela desde Ajustes > tu nombre > Suscripciones. Eliminar SnapInbox no cancela. Usa Restaurar compras con el mismo Apple Account.\n## 4. Reembolsos y fin\nApple gestiona reembolsos en https://reportaproblem.apple.com. Al finalizar el periodo se desactivan funciones Pro y los datos locales no se borran automáticamente. Soporte: romerodev.app@gmail.com.', E'These terms complement the Terms of Use and Privacy Policy. Apple displays price, taxes, currency, duration, and eligibility before confirmation.\n## 1. Plans\nSnapInbox Pro may offer monthly and annual auto-renewable plans for Premium features.\n## 2. Renewal\nThe subscription renews automatically unless canceled at least 24 hours before the current period ends. Apple may charge within the preceding 24 hours.\n## 3. Manage and restore\nManage or cancel in Settings > your name > Subscriptions. Deleting SnapInbox does not cancel it. Use Restore Purchases with the same Apple Account.\n## 4. Refunds and end\nApple handles refunds at https://reportaproblem.apple.com. When the period ends, Pro features are disabled and local data is not automatically erased. Support: romerodev.app@gmail.com.', now());
end
$migration$;
